WITH base AS (SELECT *, CAST(duration_sec AS STRING) AS duration_sec_num, COALESCE(page, 'DIRECT') AS resolved_page FROM web_events WHERE page IS DISTINCT FROM '/product') SELECT id, session_id, page, duration_sec_num, RANK() OVER (PARTITION BY event_type, page ORDER BY duration_sec DESC) AS duration_sec_rank, SUM(duration_sec) OVER (PARTITION BY event_type ORDER BY CAST(event_time AS BIGINT) RANGE BETWEEN 604800 PRECEDING AND CURRENT ROW) AS duration_sec_sum_7d FROM base
